def keyPressEvent(self, event):
    """Handle key press events"""
    if event.key() == Qt.Key_Return or event.key() == Qt.Key_Enter:
        if self.is_valid():
            self.selected()
            QComboBox.keyPressEvent(self, event) # Insert item in combo box
    else:
        QComboBox.keyPressEvent(self, event)

